/**
 * view-meta-loader.cjs — the ONE way a Node script reads the shipped VIEW_META.
 *
 * `src/core/view-meta.js` is ESM holding a plain object literal plus three accessors, so a script
 * can evaluate it directly: strip the `export` keywords, run it, read the binding. Three generators
 * and one validator had each grown their own copy of that trick — the repo's own duplication gate
 * flagged them — so it lives here instead. One implementation, one place to fix.
 *
 * ⚠️ Node-only tooling. It never ships: the free build receives the map through
 * `src/editions/*.free.js` (generated by scripts/generate-free-map.cjs).
 */
const path = require('node:path');
const fs = require('node:fs');

const ROOT = path.join(__dirname, '..', '..');
const META_FILE = path.join(ROOT, 'src', 'core', 'view-meta.js');

/** Evaluate a view-meta SOURCE STRING and return its VIEW_META binding. */
function evalViewMetaSource(source) {
  const body = source
    .replace(/^export\s+default\s+/gm, 'const __defaultExport = ')
    .replace(/^export\s+/gm, '');
  const factory = new Function(`${body}\nreturn { VIEW_META };`);
  const { VIEW_META } = factory();
  if (!VIEW_META || typeof VIEW_META !== 'object') {
    throw new Error('view-meta.js did not expose VIEW_META');
  }
  return VIEW_META;
}

/** Read and evaluate the real `src/core/view-meta.js`. */
function loadViewMeta() {
  return evalViewMetaSource(fs.readFileSync(META_FILE, 'utf8'));
}

module.exports = { ROOT, META_FILE, loadViewMeta, evalViewMetaSource };
